import{_ as s}from"./chunks/6.DpdggSBj.js";import{_ as l}from"./chunks/image1.YJCAcCic.js";import{_ as d}from"./chunks/image1.CDwWxNA4.js";import{_ as g,a as c}from"./chunks/image.DUp49IjQ.js";import{_ as h,a as e,b as m,c as p}from"./chunks/image4.FCpLmD95.js";import{_ as u}from"./chunks/image3.BUZWMjKY.js";import{_ as o}from"./chunks/image.BikqRkQy.js";import{_ as f}from"./chunks/image14.CLKeYbCZ.js";import{_,a}from"./chunks/image.DXQ6aG5l.js";import{_ as y}from"./chunks/image6.BT6bI8ah.js";import{_ as w,a as i,b as v,c as b}from"./chunks/community.D8XXOc5B.js";import{_ as x}from"./chunks/image1.DZlgADbn.js";import{_ as S}from"./chunks/image6.Cdq5CsCC.js";import{_ as k,C as P,o as C,c as z,aj as n,E as T}from"./chunks/framework.Cwzc8Cgk.js";const q="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1.Dv-L52No.png",A="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image2.2KE4YgbH.png",D="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image3.DokBx4jF.png",Z=JSON.parse('{"title":"3.6 Sign Navigation Car","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.6 Sign Navigation Car.md","filePath":"docs/3. Creative Building & Styling/3.6 Sign Navigation Car.md"}'),B={name:"docs/3. Creative Building & Styling/3.6 Sign Navigation Car.md"};function I(R,t,E,L,N,j){const r=P("pdf");return C(),z("div",null,[t[0]||(t[0]=n('<h1 id="_3-6-sign-navigation-car" tabindex="-1">3.6 Sign Navigation Car <a class="header-anchor" href="#_3-6-sign-navigation-car" aria-label="Permalink to &quot;3.6 Sign Navigation Car&quot;">​</a></h1><h2 id="_3-6-1-lesson-introduction" tabindex="-1">3.6.1 Lesson Introduction <a class="header-anchor" href="#_3-6-1-lesson-introduction" aria-label="Permalink to &quot;3.6.1 Lesson Introduction&quot;">​</a></h2><p>The Sign Navigation Car is an intelligent mobile robotics project. The front of the chassis features the WonderLens vision module serving as visual &quot;eyes&quot;, the body incorporates a dot matrix display for directional feedback, and the left and right wheels are driven by two 360° block motors to achieve differential driving. The modular mechanical structure ensures straightforward assembly and accessible wiring. When the camera recognizes traffic sign cards pointing in various directions, the dot matrix display outputs matching directional arrows, and the dual servos execute forward, backward, left turn, and right turn maneuvers. This project demonstrates practical AI traffic sign recognition and dual-servo differential drive locomotion.</p><img loading="lazy" height="1080" width="1080" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_3-6-2-learning-objectives" tabindex="-1">3.6.2 Learning Objectives <a class="header-anchor" href="#_3-6-2-learning-objectives" aria-label="Permalink to &quot;3.6.2 Learning Objectives&quot;">​</a></h2><ol><li>Master traffic sign recognition using the WonderLens vision module. Learn methods for reading forward, backward, left turn, and right turn sign signals.</li><li>Program dual 360° block motor differential drive routines to control fundamental driving maneuvers including forward motion, steering, and reversing.</li><li>Master directional arrow programming on the dot matrix module. Coordinate traffic sign recognition, directional screen prompts, and dual-servo driving motions.</li><li>Assemble the robotic car and debug the program. Develop foundational skills in building AI visual navigation mobile robotics.</li></ol><h2 id="_3-6-3-assembly-guide" tabindex="-1">3.6.3 Assembly Guide <a class="header-anchor" href="#_3-6-3-assembly-guide" aria-label="Permalink to &quot;3.6.3 Assembly Guide&quot;">​</a></h2>',7)),T(r,{src:"../../_static/shared/pdf/chapter_3/6.pdf"}),t[1]||(t[1]=n('<h2 id="_3-6-4-hardware-wiring" tabindex="-1">3.6.4 Hardware Wiring <a class="header-anchor" href="#_3-6-4-hardware-wiring" aria-label="Permalink to &quot;3.6.4 Hardware Wiring&quot;">​</a></h2><p>Connect the WonderLens vision module cable to port <strong>P1</strong> of the ESP32 controller.</p><p>Connect the dot matrix module cable to port <strong>P5</strong> of the ESP32 controller.</p><p>Connect the left 360° block motor cable to port <strong>S1</strong> of the ESP32 controller, with the servo&#39;s <strong>orange</strong> wire plugged into the <strong>white</strong> pin of S1.</p><p>Connect the right 360° block motor cable to port <strong>S2</strong> of the ESP32 controller, with the servo&#39;s <strong>orange</strong> wire plugged into the <strong>white</strong> pin of S2.</p><p>Wiring diagram:</p><img loading="lazy" height="1220" width="1490" src="'+q+'" class="common_img" style="width:500px;"><h2 id="_3-6-5-programming" tabindex="-1">3.6.5 Programming <a class="header-anchor" href="#_3-6-5-programming" aria-label="Permalink to &quot;3.6.5 Programming&quot;">​</a></h2><h3 id="_1-program-schematic" tabindex="-1">(1) Program Schematic <a class="header-anchor" href="#_1-program-schematic" aria-label="Permalink to &quot;(1) Program Schematic&quot;">​</a></h3><img loading="lazy" height="490" width="370" src="'+A+'" class="common_img" style="width:350px;"><h3 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2) Adding Extensions&quot;">​</a></h3><ul><li>Click the <strong>Extensions</strong> button and select the <strong>WonderLens</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><ul><li>Click the <strong>Extensions</strong> button and select <strong>Dot matrix module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+d+'" class="common_img" style="width:800px;"><h3 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Function Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="303" width="408" src="'+g+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+c+'" class="common_img"></td><td style="text-align:left;">Compares the value on the left with a custom value and outputs a Boolean result for the greater-than comparison.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="41" width="173" src="'+h+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+e+'" class="common_img"></td><td style="text-align:left;">Creates a custom variable to store data.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="115" width="312" src="'+m+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+e+'" class="common_img"></td><td style="text-align:left;">Reads the value stored in the specified variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="138" width="522" src="'+p+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+e+'" class="common_img"></td><td style="text-align:left;">Assigns a custom value to the specified variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="75" width="553" src="'+u+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="51" width="75" src="'+o+'" class="common_img"></td><td style="text-align:left;">Plays audio according to custom pitch, beat duration, and playback mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="108" width="524" src="'+f+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="51" width="75" src="'+o+'" class="common_img"></td><td style="text-align:left;">Controls the servo connected to the specified port to rotate at the set speed.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="114" width="251" src="'+_+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="67" width="75" src="'+a+'" class="common_img"></td><td style="text-align:left;">Adjusts the brightness level of the dot matrix display within the range of 1 to 8.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="101" width="255" src="'+y+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="67" width="75" src="'+a+'" class="common_img"></td><td style="text-align:left;">Draws selected graphic patterns on the dot matrix display.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="412" width="760" src="'+w+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+i+'" class="common_img"></td><td style="text-align:left;">Switches the AI vision operating mode of the vision module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="117" width="432" src="'+v+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+i+'" class="common_img"></td><td style="text-align:left;">Refreshes the camera feed and reads recognition data for the current vision mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="97" width="807" src="'+x+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+i+'" class="common_img"></td><td style="text-align:left;">Extracts the traffic sign ID with the highest confidence score from the recognition results.</td></tr></tbody></table><h3 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h3><ol><li><p>Initialization: At startup, initialize the WonderLens vision module at port <strong>P1</strong> and switch the operating mode to traffic sign recognition. Initialize the dot matrix module at port <strong>P5</strong> and set the brightness level to 5. Set the initial speeds of servos <strong>S1</strong> and <strong>S2</strong> to 0, and pause for 1 s.</p></li><li><p>Main Loop: The program continuously updates and retrieves recognition results from the WonderLens vision module, extracting the traffic sign ID with the highest confidence score and storing it in the variable <code>Result</code>. When <code>Result</code> equals 1, 2, 3, or 4, the dot matrix display sequentially shows upward, rightward, leftward, or downward arrows, the buzzer plays prompt note C4, and servos <strong>S1</strong> and <strong>S2</strong> rotate at corresponding speeds and durations to execute forward, right turn, left turn, or reverse maneuvers. Upon completing the maneuver, both servos halt, the dot matrix display clears, and each loop iteration pauses for 0.1 s.</p></li></ol><img loading="lazy" height="2117" width="559" src="'+D+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1gpd83ho-Cf-T1LV6VETKvwf1mI7A8Bfg?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-6-6-program-upload" tabindex="-1">3.6.6 Program Upload <a class="header-anchor" href="#_3-6-6-program-upload" aria-label="Permalink to &quot;3.6.6 Program Upload&quot;">​</a></h2><img loading="lazy" height="360" width="640" src="'+S+'" class="common_img" style="width:800px;"><h2 id="_3-6-7-expansion-and-challenge" tabindex="-1">3.6.7 Expansion and Challenge <a class="header-anchor" href="#_3-6-7-expansion-and-challenge" aria-label="Permalink to &quot;3.6.7 Expansion and Challenge&quot;">​</a></h2><p><strong>Challenge Task 1: Multi-Sign Navigation Linked with RGB Lighting</strong></p><ol><li><p>Project Goal: Match distinct traffic signs to dedicated RGB lighting effects and driving speeds, stopping the car with a standby prompt when no sign is detected. Forward sign: RGB glows solid green, and the car travels forward at constant speed. Left turn sign: RGB pulses blue, and the car turns left slowly. Right turn sign: RGB pulses orange, and the car turns right slowly. Backward sign: RGB flashes red, and the car reverses at low speed. No valid sign detected: the car pauses in place, and the dot matrix display shows a waiting icon.</p></li><li><p>Implementation Strategy: Retrieve traffic sign recognition results and construct multi-branch conditional statements. Configure corresponding dual-servo differential drive parameters, RGB lighting colors, and dot matrix arrow patterns for each sign branch. Program the empty detection branch to halt the car and display the waiting icon.</p></li><li><p>Key Challenges: Reading traffic signs stably without false triggers, synchronizing locomotion, lighting, and screen graphics smoothly, and maintaining responsive dual-servo execution without system lag.</p></li></ol><p><strong>Challenge Task 2: Delayed Braking After Sign Disappearance</strong></p><ol><li><p>Project Goal: When a traffic sign moves out of camera view, the car does not halt immediately. It maintains its current motion for 3 s. Once the countdown expires, both servos halt, the RGB lights extinguish, and the dot matrix switches to the waiting icon.</p></li><li><p>Implementation Strategy: Introduce a timer variable to start a countdown when the sign disappears. Maintain ongoing driving motions and lighting effects while the countdown runs. Stop the car, turn off the lights, and display the waiting icon once the timer reaches zero.</p></li><li><p>Key Challenges: Ensuring that the timing routine does not interfere with continuous camera sign detection loops, and synchronizing dual servos, lighting, and display outputs without latency.</p></li></ol><p><strong>Challenge Task 3: Creative Applications of Traffic Sign Recognition</strong></p><ol><li><p>Smart Directional Signpost: Retain the traffic sign recognition algorithm, omit the drive servos, and pair the system with RGB lights and a dot matrix display to show directional text and change lighting colors upon recognizing signs.</p></li><li><p>Sorting and Classifying Transporter: Recognize distinct marker signs and control a servo-driven paddle to divert items into corresponding sorting zones.</p></li><li><p>Universal Adaptation Strategy: Keep the core traffic sign recognition code unchanged and swap out the output hardware. By adding corresponding peripheral control blocks under the logic of triggering actions upon detecting designated signs, diverse intelligent robotics projects can be developed.</p></li></ol><h2 id="_3-6-8-q-a" tabindex="-1">3.6.8 Q&amp;A <a class="header-anchor" href="#_3-6-8-q-a" aria-label="Permalink to &quot;3.6.8 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: During servo wiring, the orange signal wire must connect to the white pin of the corresponding S port. What problems occur if it is wired incorrectly?</strong></p><p><strong>Answer</strong>: The white pins of ports <strong>S1</strong> and <strong>S2</strong> are dedicated to transmitting PWM control signals, which the servos rely on to determine rotation angles and speeds. If the orange signal wire connects to the power or ground pins, the controller cannot transmit control instructions. Two primary failures occur: either the wheel servo on that side remains completely motionless so the car cannot travel straight or steer, or the servo vibrates and rotates erratically, potentially overheating and causing hardware damage. Furthermore, all program code designated to control car driving and steering becomes ineffective, preventing sign-guided autonomous navigation.</p><p><strong>Question 2: The vision module recognizes traffic signs normally and the dot matrix display shows directional arrows, but the car wheels do not move at all. What are the most common causes and troubleshooting steps?</strong></p><p><strong>Answer</strong>:</p><ol><li><p>Wiring Fault: The orange signal wires of the left and right servos are not plugged into the white signal pins of ports <strong>S1</strong> and <strong>S2</strong> respectively. Troubleshooting: Disconnect the power, then verify the three-pin sequence on both sides against the wiring diagram.</p></li><li><p>Program Fault: The dual-servo differential drive code is placed outside the condition branch for detecting valid traffic signs. Troubleshooting: Open the program and verify that the left and right servo control and delay blocks reside inside the conditional block that executes when traffic sign recognition succeeds.</p></li><li><p>Hardware Damage: One or both servos are defective or ports <strong>S1</strong> and <strong>S2</strong> of the ESP32 controller are damaged. Troubleshooting: Connect a known working servo to ports <strong>S1</strong> and <strong>S2</strong> for testing. If it still fails to move, connect the servo to an alternative servo port on the controller to isolate the issue.</p></li></ol><h2 id="_3-6-9-technical-support-and-product-discussion" tabindex="-1">3.6.9 Technical Support and Product Discussion <a class="header-anchor" href="#_3-6-9-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.6.9 Technical Support and Product Discussion&quot;">​</a></h2><p>Share project ideas and connect with other makers on the <a href="https://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder community</a>:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+b+'" class="common_img" style="width:800px;"></a>',39))])}const tt=k(B,[["render",I]]);export{Z as __pageData,tt as default};
